fn old_document_generations_are_kept_by_references_without_an_eviction_limit() {
    let mut runtime = runtime();
    runtime
        .eval("var frame = document.getElementById('f'); var held = [];")
        .unwrap();
    // Each navigation is a separate script job, as it would be when initiated
    // by successive page tasks. Keep all 80 generations reachable throughout.
    for index in 0..80 {
        runtime
            .eval(&format!(
                "frame.srcdoc = '<p>{index}</p>'; held.push(frame.contentDocument);"
            ))
            .unwrap();
    }
    collect(&mut runtime);
    assert_eq!(
        runtime
            .eval("held.every((doc, i) => doc.body.textContent === String(i))")
            .unwrap()
            .as_boolean(),
        Some(true)
    );
    runtime.eval("held = null").unwrap();
    collect(&mut runtime);
    let state = runtime.host_state.borrow();
    assert!(
        state.node_lifetimes.document_count() <= 2,
        "only main and current iframe documents remain"
    );
    assert!(
        state.node_lifetimes.node_count() < 30,
        "retired nodes must be reclaimed"
    );
    assert!(state.document_styles.len() <= 2);
}
